-- Product ids follow the four designs (ADR 0012). Run once, before the code that uses the new ids is deployed.
-- Only ids change; quantities and order snapshots (names, prices) stay as they are.
-- One statement per line so the owner can paste them into the D1 console one by one.
UPDATE inventory SET product_id = CASE product_id WHEN 'bow-white' THEN 'wide-tie-white' WHEN 'bow-silver' THEN 'wide-tie-silver' WHEN 'bow-gold' THEN 'wide-tie-gold' WHEN 'bow-mustard' THEN 'wide-tie-mustard' WHEN 'bow-burgundy' THEN 'wide-tie-burgundy' WHEN 'bow-taupe' THEN 'wide-tie-taupe' WHEN 'sash-red' THEN 'wide-tie-red' WHEN 'sash-black' THEN 'wide-tie-black' WHEN 'sash-blush' THEN 'wide-tie-blush' WHEN 'sash-green' THEN 'wide-tie-green' WHEN 'sash-cognac' THEN 'wide-tie-cognac' WHEN 'sash-brown' THEN 'wide-tie-brown' WHEN 'twist-grey' THEN 'wide-tie-grey' WHEN 'classic-white' THEN 'thin-tie-white' WHEN 'classic-red' THEN 'thin-tie-red' WHEN 'classic-rose' THEN 'thin-tie-rose' WHEN 'classic-mustard' THEN 'thin-tie-mustard' WHEN 'classic-green' THEN 'thin-tie-green' WHEN 'classic-sky-blue' THEN 'thin-tie-sky-blue' WHEN 'classic-royal-blue' THEN 'thin-tie-royal-blue' WHEN 'classic-navy' THEN 'thin-tie-navy' WHEN 'classic-pink-suede' THEN 'thin-tie-pink' WHEN 'classic-orange-suede' THEN 'thin-tie-orange' WHEN 'classic-camel-suede' THEN 'thin-tie-camel' WHEN 'croc-black' THEN 'thin-tie-croc-black' WHEN 'croc-wine' THEN 'thin-tie-croc-wine' WHEN 'croc-pink' THEN 'thin-tie-croc-pink' WHEN 'croc-cognac' THEN 'thin-tie-croc-cognac' WHEN 'snake-grey' THEN 'thin-tie-snake-grey' WHEN 'snake-beige' THEN 'thin-tie-snake-beige' ELSE product_id END WHERE product_id IN ('bow-white', 'bow-silver', 'bow-gold', 'bow-mustard', 'bow-burgundy', 'bow-taupe', 'sash-red', 'sash-black', 'sash-blush', 'sash-green', 'sash-cognac', 'sash-brown', 'twist-grey', 'classic-white', 'classic-red', 'classic-rose', 'classic-mustard', 'classic-green', 'classic-sky-blue', 'classic-royal-blue', 'classic-navy', 'classic-pink-suede', 'classic-orange-suede', 'classic-camel-suede', 'croc-black', 'croc-wine', 'croc-pink', 'croc-cognac', 'snake-grey', 'snake-beige');
UPDATE order_items SET product_id = CASE product_id WHEN 'bow-white' THEN 'wide-tie-white' WHEN 'bow-silver' THEN 'wide-tie-silver' WHEN 'bow-gold' THEN 'wide-tie-gold' WHEN 'bow-mustard' THEN 'wide-tie-mustard' WHEN 'bow-burgundy' THEN 'wide-tie-burgundy' WHEN 'bow-taupe' THEN 'wide-tie-taupe' WHEN 'sash-red' THEN 'wide-tie-red' WHEN 'sash-black' THEN 'wide-tie-black' WHEN 'sash-blush' THEN 'wide-tie-blush' WHEN 'sash-green' THEN 'wide-tie-green' WHEN 'sash-cognac' THEN 'wide-tie-cognac' WHEN 'sash-brown' THEN 'wide-tie-brown' WHEN 'twist-grey' THEN 'wide-tie-grey' WHEN 'classic-white' THEN 'thin-tie-white' WHEN 'classic-red' THEN 'thin-tie-red' WHEN 'classic-rose' THEN 'thin-tie-rose' WHEN 'classic-mustard' THEN 'thin-tie-mustard' WHEN 'classic-green' THEN 'thin-tie-green' WHEN 'classic-sky-blue' THEN 'thin-tie-sky-blue' WHEN 'classic-royal-blue' THEN 'thin-tie-royal-blue' WHEN 'classic-navy' THEN 'thin-tie-navy' WHEN 'classic-pink-suede' THEN 'thin-tie-pink' WHEN 'classic-orange-suede' THEN 'thin-tie-orange' WHEN 'classic-camel-suede' THEN 'thin-tie-camel' WHEN 'croc-black' THEN 'thin-tie-croc-black' WHEN 'croc-wine' THEN 'thin-tie-croc-wine' WHEN 'croc-pink' THEN 'thin-tie-croc-pink' WHEN 'croc-cognac' THEN 'thin-tie-croc-cognac' WHEN 'snake-grey' THEN 'thin-tie-snake-grey' WHEN 'snake-beige' THEN 'thin-tie-snake-beige' ELSE product_id END WHERE product_id IN ('bow-white', 'bow-silver', 'bow-gold', 'bow-mustard', 'bow-burgundy', 'bow-taupe', 'sash-red', 'sash-black', 'sash-blush', 'sash-green', 'sash-cognac', 'sash-brown', 'twist-grey', 'classic-white', 'classic-red', 'classic-rose', 'classic-mustard', 'classic-green', 'classic-sky-blue', 'classic-royal-blue', 'classic-navy', 'classic-pink-suede', 'classic-orange-suede', 'classic-camel-suede', 'croc-black', 'croc-wine', 'croc-pink', 'croc-cognac', 'snake-grey', 'snake-beige');
